source='''from collections import defaultdict, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            minr = min(y for y,x in cells); maxr = max(y for y,x in cells)
            minc = min(x for y,x in cells); maxc = max(x for y,x in cells)
            if len(cells) == (maxr-minr+1)*(maxc-minc+1):
                comps.append((color, minr, maxr, minc, maxc))
    totals = defaultdict(int)
    for color, r0, r1, c0, c1 in comps:
        totals[color] += (r1-r0+1)*(c1-c0+1)
    if not totals:
        return [row[:] for row in grid]
    base = max(totals, key=totals.get)
    out = [row[:] for row in grid]
    for color in totals:
        if color == base:
            continue
        objs = [b for b in comps if b[0] == color]
        # Join horizontally aligned shapes, painting only the empty separator cells.
        groups = defaultdict(list)
        for _, r0, r1, c0, c1 in objs:
            groups[(r0, r1)].append((c0, c1))
        for (r0, r1), spans in groups.items():
            spans.sort()
            for (_, left_end), (right_start, _) in zip(spans, spans[1:]):
                for r in range(r0, r1+1):
                    for c in range(left_end+1, right_start):
                        if grid[r][c] == 0:
                            out[r][c] = color
        # Join vertically aligned shapes.
        groups = defaultdict(list)
        for _, r0, r1, c0, c1 in objs:
            groups[(c0, c1)].append((r0, r1))
        for (c0, c1), spans in groups.items():
            spans.sort()
            for (_, top_end), (bottom_start, _) in zip(spans, spans[1:]):
                for r in range(top_end+1, bottom_start):
                    for c in range(c0, c1+1):
                        if grid[r][c] == 0:
                            out[r][c] = color
    return out
'''
